H.background();
const w = H.W, hh = H.H;
const a = Math.round(P.a), b = Math.round(P.b);
const rel = Math.round(P.rel) % 4; // is / at least / at most / more than
const q = String.fromCharCode(34);
// "three times a number, <relation>, b"  ->  3x <rel> b
const relWords = ["is equal to", "is at least", "is at most", "is more than"];
const relSym   = ["=", ">=", "<=", ">"];
const sentence = q + a + " times a number " + relWords[rel] + " " + b + q;
const algebra  = a + " * x " + relSym[rel] + " " + b;
H.text("Translate a sentence to an equation / inequality", 24, 32, { color: H.colors.ink, size: 18, weight: 700 });
H.text("Relationship words pick the symbol: 'is' -> = , 'at least' -> >= , 'at most' -> <= .", 24, 54, { color: H.colors.sub, size: 12 });
H.rect(50, 92, w - 100, 50, { fill: H.colors.panel, stroke: H.colors.grid, width: 1, radius: 10 });
H.text(sentence, 68, 123, { color: H.colors.ink, size: 18, weight: 600 });
const ay = 158 + 5 * Math.sin(t * 2.5);
H.arrow(w * 0.5, 146, w * 0.5, ay + 10, { color: H.colors.accent2, width: 3 });
H.rect(50, 188, w - 100, 50, { fill: "#13243f", stroke: H.colors.accent, width: 2, radius: 10 });
H.text(algebra, 68, 220, { color: H.colors.good, size: 24, weight: 700 });
// number line: solution of  a*x <rel> b  ->  x <rel'> b/a  (a assumed > 0)
const aa = a === 0 ? 1 : a;
const bound = b / aa;
const v = H.plot2d({ xMin: -10, xMax: 10, yMin: -1, yMax: 1, pad: 50 });
v.line(-10, 0, 10, 0, { color: H.colors.axis, width: 2 });
for (let k = -10; k <= 10; k += 2) { v.line(k, -0.12, k, 0.12, { color: H.colors.grid, width: 1.5 }); v.text(String(k), k, -0.45, { color: H.colors.sub, size: 11, align: "center" }); }
const cb = Math.max(-10, Math.min(10, bound));
// shade the solution region (skip for strict equality)
if (rel !== 0) {
  const goRight = rel === 1 || rel === 3; // at least / more than
  const x2 = goRight ? 10 : -10;
  v.line(cb, 0.18, x2, 0.18, { color: H.colors.good, width: 5 });
}
const open = rel === 3; // strict -> open circle
v.dot(cb, 0, { r: 7, fill: open ? H.colors.bg : H.colors.warn, stroke: H.colors.warn });
v.text("x " + relSym[rel] + " " + bound.toFixed(2), cb, 0.6, { color: H.colors.warn, size: 13, align: "center" });
// animated test point checking the inequality
const tx = 8 * Math.sin(t * 0.6);
const holds = rel === 0 ? Math.abs(aa * tx - b) < 0.3 : rel === 1 ? aa * tx >= b : rel === 2 ? aa * tx <= b : aa * tx > b;
v.dot(tx, -0.0, { r: 5, fill: holds ? H.colors.good : H.colors.sub });
H.text("a = " + a + "   b = " + b + "   ->   " + algebra + "   (x " + relSym[rel] + " " + bound.toFixed(2) + ")", 24, hh - 22, { color: H.colors.sub, size: 13 });
